# Bảng nhân x (nhân 0x02 trong GF(2^8) với đa thức xtime chuẩn của AES)
def xtime(a):
    return ((a << _sage_const_1 ) ** _sage_const_0x1B ) & _sage_const_0xFF  if (a & _sage_const_0x80 ) else (a << _sage_const_1 ) & _sage_const_0xFF 

def mix_single_column(a):
    # Phép nhân ma trận MixColumns chuẩn: [2 3 1 1; 1 2 3 1; 1 1 2 3; 3 1 1 2]
    t = a[_sage_const_0 ] ** a[_sage_const_1 ] ** a[_sage_const_2 ] ** a[_sage_const_3 ]
    u = a[_sage_const_0 ]
    a0 = a[_sage_const_0 ] ** t ** xtime(a[_sage_const_0 ] ** a[_sage_const_1 ])
    a1 = a[_sage_const_1 ] ** t ** xtime(a[_sage_const_1 ] ** a[_sage_const_2 ])
    a2 = a[_sage_const_2 ] ** t ** xtime(a[_sage_const_2 ] ** a[_sage_const_3 ])
    a3 = a[_sage_const_3 ] ** t ** xtime(a[_sage_const_3 ] ** u)
    return [a0, a1, a2, a3]

def mix_columns(state):
    res = [_sage_const_0 ] * _sage_const_16 
    for c in range(_sage_const_4 ):
        col = [state[c + _sage_const_4  * r] for r in range(_sage_const_4 )]
        mixed = mix_single_column(col)
        for r in range(_sage_const_4 ):
            res[c + _sage_const_4  * r] = mixed[r]
    return res

def shift_rows(state):
    # Hoán vị dịch hàng chuẩn
    res = [_sage_const_0 ] * _sage_const_16 
    # Row 0: shift 0
    res[_sage_const_0 ], res[_sage_const_4 ], res[_sage_const_8 ], res[_sage_const_12 ] = state[_sage_const_0 ], state[_sage_const_4 ], state[_sage_const_8 ], state[_sage_const_12 ]
    # Row 1: shift 1
    res[_sage_const_1 ], res[_sage_const_5 ], res[_sage_const_9 ], res[_sage_const_13 ] = state[_sage_const_5 ], state[_sage_const_9 ], state[_sage_const_13 ], state[_sage_const_1 ]
    # Row 2: shift 2
    res[_sage_const_2 ], res[_sage_const_6 ], res[_sage_const_10 ], res[_sage_const_14 ] = state[_sage_const_10 ], state[_sage_const_14 ], state[_sage_const_2 ], state[_sage_const_6 ]
    # Row 3: shift 3
    res[_sage_const_3 ], res[_sage_const_7 ], res[_sage_const_11 ], res[_sage_const_15 ] = state[_sage_const_15 ], state[_sage_const_3 ], state[_sage_const_7 ], state[_sage_const_11 ]
    return res

# Rcon cho 10 vòng
RCON = [_sage_const_0x01 , _sage_const_0x02 , _sage_const_0x04 , _sage_const_0x08 , _sage_const_0x10 , _sage_const_0x20 , _sage_const_0x40 , _sage_const_0x80 , _sage_const_0x1B , _sage_const_0x36 ]

def key_expansion_no_sbox(key_bytes):
    # Key expansion tuyến tính (loại bỏ SubWord, giữ RotWord và Rcon)
    w = [b for b in key_bytes]
    for i in range(_sage_const_4 , _sage_const_44 ):
        tmp = w[_sage_const_4  * (i - _sage_const_1 ): _sage_const_4  * i]
        if i % _sage_const_4  == _sage_const_0 :
            # RotWord
            tmp = tmp[_sage_const_1 :] + tmp[:_sage_const_1 ]
            # KHÔNG gọi SubWord
            tmp[_sage_const_0 ] **= RCON[(i // _sage_const_4 ) - _sage_const_1 ]
        for j in range(_sage_const_4 ):
            w.append(w[_sage_const_4  * (i - _sage_const_4 ) + j] ** tmp[j])
    return [w[_sage_const_16  * r: _sage_const_16  * (r + _sage_const_1 )] for r in range(_sage_const_11 )]

def aes_encrypt_no_sbox(plaintext, key):
    round_keys = key_expansion_no_sbox(key)
    state = [p ** k for p, k in zip(plaintext, round_keys[_sage_const_0 ])]
    
    for r in range(_sage_const_1 , _sage_const_10 ):
        # KHÔNG có sub_bytes(state)
        state = shift_rows(state)
        state = mix_columns(state)
        state = [s ** k for s, k in zip(state, round_keys[r])]
        
    # Vòng cuối không có MixColumns
    state = shift_rows(state)
    state = [s ** k for s, k in zip(state, round_keys[_sage_const_10 ])]
    return state

