# 2. Xử lý biểu diễn Vector trên GF(2)
# ==========================================

def bytes_to_gf2_vector(b_arr):
    bits = []
    for byte in b_arr:
        for bit_idx in range(_sage_const_8 ):
            bits.append((byte >> (_sage_const_7  - bit_idx)) & _sage_const_1 )
    return vector(GF(_sage_const_2 ), bits)

def gf2_vector_to_bytes(v):
    b_arr = []
    for byte_idx in range(_sage_const_16 ):
        byte_val = _sage_const_0 
        for bit_idx in range(_sage_const_8 ):
            byte_val = (byte_val << _sage_const_1 ) | int(v[byte_idx * _sage_const_8  + bit_idx])
        b_arr.append(byte_val)
    return bytes(b_arr)

